  "{count} downloading": "{count} sa sťahuje",
  "{count} earlier episodes in this season are still unwatched.": "{count} skorších epizód v tejto sezóne je stále nepozretých.",
  "{count} earlier seasons are still unwatched.": "{count} skorších sezón je stále nepozretých.",
  "{count} episodes": "{count} epizód",
  "{count} lines": "{count} riadkov",
